def _apply_links(
    components: _Components, by_content_key: dict[ContentKey, str], ordered: Sequence[IdentityLink]
) -> tuple[int, int]:
    """Merge links best first; return (dropped by one-to-one, refused as same-sheet conflicts)."""
    taken: set[tuple[ContentKey, str]] = set()  # (occurrence, the other sheet it is linked to)
    n_dropped = n_conflicts = 0
    for link in ordered:
        slots = {(link.first, link.second.sheet_id), (link.second, link.first.sheet_id)}
        if slots & taken:
            n_dropped += 1
            continue
        one, other = _local_key(by_content_key, link.first), _local_key(by_content_key, link.second)
        if components.merge(one, other):
            taken |= slots  # only a link that really merged uses up its slots
        else:
            n_conflicts += 1
    return n_dropped, n_conflicts

def _upstream_walk(
    plant: nx.DiGraph[str], node_id: str
) -> tuple[frozenset[str], frozenset[tuple[str, str]]] | None:
    """Walk upstream from `node_id`: `(valves, edges walked)`, or `None` if a route has no valve.

    `None` means the precondition fails: some route ends at a source (a node
    nothing flows into) before meeting an operated valve. There is no hop
    cap (ADR-0029): the `seen` set stops the walk at cycles and re-joins, so
    it visits each node once and always ends.
    """
    valves: set[str] = set()
    edges: set[tuple[str, str]] = set()
    seen = {node_id}
    frontier = [node_id]
    while frontier:
        next_frontier: list[str] = []
        for current in frontier:
            upstream = _send_to_predecessors(plant, current)
            if not upstream:
                return None  # a route with nothing on it to close
            edges.update((p, current) for p in upstream)
            for predecessor in upstream:
                _visit(plant, predecessor, valves, seen, next_frontier)
        frontier = next_frontier
    return frozenset(valves), frozenset(edges)

def item_valve_counts(
    plant: nx.DiGraph[str], source_id: str, hops: dict[str, dict[str, ItemHop]] | None = None
) -> dict[str, frozenset[int]]:
    """For each item reachable from the source: the valve counts of its item-level shortest routes.

    A hop is one item to the next (fittings are passed through, as `next_path_items` does), and
    "between" means the items strictly inside the route. One breadth-first layer at a time, an
    item collects the counts of its predecessors in the previous layer, plus that predecessor
    if it is a valve. More than one count in a set means the pair is ambiguous.

    Args:
        plant: the plant graph.
        source_id: the equipment item the routes start at.
        hops: `item_hops(plant)`, passed in when many sources are walked, to build it only once.
    """
    hops = item_hops(plant) if hops is None else hops
    counts = {source_id: frozenset({0})}
    frontier = [source_id]
    while frontier:
        found: dict[str, set[int]] = {}
        for node_id in frontier:
            add = 1 if plant.nodes[node_id]["node_class"] in VALVE_CLASSES else 0
            for next_id in hops[node_id]:
                if next_id not in counts:
                    found.setdefault(next_id, set()).update(c + add for c in counts[node_id])
        counts.update({node_id: frozenset(values) for node_id, values in found.items()})
        frontier = sorted(found)
    return counts

