def run_cap_usd(dry_cap_usd: float, root: Path, step_dir: Path, step_ceiling_usd: float) -> float:
    """The cap one run may use: its dry-run cap, bounded by its step's ceiling and by the ledger.

    Three limits apply and the smallest wins: the dry run's cap, what is left of the step's ceiling
    (the step's own spend so far is read from `step_dir`), and what is left of the $30 runs ledger.

    Raises:
        LedgerExhausted: the step's ceiling or the runs ledger has nothing left.
    """
    step_left = step_ceiling_usd - runs_spent_usd(step_dir)
    ledger_left = RUNS_CAP_USD - runs_spent_usd(root)
    if step_left <= 0:
        raise LedgerExhausted(
            f"expected money left under the step ceiling ${step_ceiling_usd:.2f}, "
            f"found ${step_left:.4f}"
        )
    if ledger_left <= 0:
        raise LedgerExhausted(
            f"expected money left under the ${RUNS_CAP_USD:.0f} runs ledger, "
            f"found ${ledger_left:.4f}"
        )
    return round(min(dry_cap_usd, step_left, ledger_left), 6)

def ask(self, asked: AskedQuestion) -> LiveAnswer | NeedsPaidCall:
    """Run tiers until the policy settles the question or the cutoff is spent.

    Returns `NeedsPaidCall` when a model call is not in the cache and the clients may not
    pay: nothing is sent. Raises `SpendCapReached` when the guard's cap would be passed.
    """
    runs: list[_TierRun] = []
    signals: dict[str, dict[str, Signals]] = {}
    used_s = 0.0
    while True:
        walk = walk_question(self._policy, asked.question_id, None, signals)
        if walk.missing_tier is None:
            break
        remaining_s = self._cutoff_s - used_s
        if remaining_s <= 0:
            return self._assemble(asked, runs, decision=None, accepted=None)
        try:
            run = self._run_tier(self._tiers[walk.missing_tier], asked, remaining_s)
        except CacheMiss as miss:
            return NeedsPaidCall(missing_tier=walk.missing_tier, reason=str(miss))
        runs.append(run)
        signals[run.tier.spec.name] = {asked.question_id: run.signals}
        used_s += run.signals.latency_s
    decision = decide(self._policy, asked.question_id, None, signals)
    return self._assemble(asked, runs, decision, accepted=walk.accepted)
